import { jsPDF } from "jspdf"

export function import_EncodeSansCond_Bold() {
    var font = "";
    var callAddFont = function () {
        this.addFileToVFS( "EncodeSansCondensed-Bold-normal.ttf", font );
        this.addFont( "EncodeSansCondensed-Bold-normal.ttf", "EncodeSansCondensed-Bold", "normal" );
    };
    jsPDF.API.events.push( [ "addFonts", callAddFont ] )
}
